  it.todo("Rule 1 - should kill two adjacent cells with 1 neighbor each ([(0,1),(1,1)] -> [])");
  it.todo("Rule 4 - should birth a dead cell with exactly 3 live neighbors (L-shape [(0,0),(1,0),(0,1)] -> [(0,0),(0,1),(1,0),(1,1)])");
  it.todo("Rule 2 - should keep live cells with exactly 3 neighbors alive (block [(0,0),(1,0),(0,1),(1,1)] -> unchanged)");
  it.todo("Rule 2/4 - blinker Gen0 -> Gen1 vertical to horizontal ([(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)])");
  it.todo("Blinker - should oscillate back on Gen2 ([(-1,1),(0,1),(1,1)] -> [(0,0),(0,1),(0,2)])");
  it.todo("Rule 3 - should kill a live cell with more than 3 neighbors (plus [(0,0),(0,1),(0,-1),(1,0),(-1,0)] -> corners/survivors without center)");
  it.todo("should handle negative coordinates (block at [(-2,-2),(-1,-2),(-2,-1),(-1,-1)] -> unchanged)");
});

